void DX8Wrapper::Set_Material(const VertexMaterialClass *material)
{
	VertexMaterialClass *new_material = const_cast<VertexMaterialClass *>(material);
	if (new_material) {
		new_material->Add_Ref();
	}
	if (render_state.material) {
		render_state.material->Release_Ref();
	}
	render_state.material = new_material;
	render_state_changed |= MATERIAL_CHANGED;
}

